import './StatusList.css';
import type { Status, StatusItem } from '../../types';

export type { Status, StatusItem };

export const STATUS_LABELS: Record<Status, string> = {
  todo: 'To Do',
  in_progress: 'In Progress',
  done: 'Done',
  blocked: 'Blocked',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: Status): string {
  switch (status) {
    case 'todo':
      return 'status-color-todo';
    case 'in_progress':
      return 'status-color-in-progress';
    case 'done':
      return 'status-color-done';
    case 'blocked':
      return 'status-color-blocked';
  }
}

interface StatusListProps {
  items: StatusItem[] | null;
}

export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    return (
      <ul className="status-list" aria-label="Loading status list">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="status-list-item status-list-skeleton">
            <span className="skeleton-pill" />
          </li>
        ))}
      </ul>
    );
  }

  const statuses = Object.keys(STATUS_LABELS) as Status[];

  return (
    <div className="status-list-container">
      {statuses.map((status) => {
        const statusItems = items.filter((item) => item.status === status);
        if (statusItems.length === 0) {
          return null;
        }
        return (
          <section key={status} className="status-group" aria-label={STATUS_LABELS[status]}>
            <h2 className={`status-group-heading ${statusColor(status)}`}>
              {STATUS_LABELS[status]}
            </h2>
            <ul className="status-list">
              {statusItems.map((item) => (
                <li key={item.id} className="status-list-item">
                  {item.name}
                </li>
              ))}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

