import './ChipFilter.css';

type FilterLabel = 'All' | 'Active' | 'Archived' | 'Starred';

const FILTERS: FilterLabel[] = ['All', 'Active', 'Archived', 'Starred'];

export function ChipFilter(): JSX.Element {
  const [pressed, setPressed] = useState<FilterLabel>('All');

  return (
    <div className="chip-bar" role="group" aria-label="Filter">
      {FILTERS.map((label) => (
