import { useState, useEffect } from 'react';
import type { StatusItem } from '../../types';
import { getTasks } from '../../api';
import './TaskBoard.css';

// null = loading; array = loaded
const SKELETON_COUNT = 5;

export function TaskBoard(): JSX.Element {
  const [tasks, setTasks] = useState<StatusItem[] | null>(null);

  useEffect(() => {
    getTasks()
      .then(setTasks)
      .catch(() => setTasks([]));
  }, []);

  function renderBody(): JSX.Element {
    if (tasks === null) {
      return (
        <ul className="task-list" aria-label="Loading tasks">
          {Array.from({ length: SKELETON_COUNT }, (_, i) => (
            <li key={i} className="task-item task-item-skeleton">
              <span className="task-skeleton-line" />
            </li>
          ))}
        </ul>
      );
    }

    if (tasks.length === 0) {
      return <p className="task-board-empty">No tasks</p>;
    }

    return (
      <ul className="task-list" aria-label="Task list">
        {tasks.map((task) => (
          <li key={task.id} className="task-item">
            {task.name}
          </li>
        ))}
      </ul>
    );
  }

  return (
    <main className="task-board" aria-label="Tasks">
      <header className="task-board-header">
        <h1 className="task-board-title">Tasks</h1>
        {tasks !== null && (
          <span className="task-board-count" role="status">
            {tasks.length}
          </span>
        )}
      </header>
      <div className="task-board-filter-bar" />
      {renderBody()}
    </main>
  );
}

