import './PriceDisplay.css';

interface Props {
  price: number;
  originalPrice?: number;
}

// Math.ceil: always round up to avoid under-charging (business rule)
function formatPrice(value: number): string {
  return `$${Math.ceil(value)}`;
}

export function PriceDisplay({ price, originalPrice }: Props): JSX.Element {
  return (
    <p className="price-display">
      <strong className="price-display-current">{formatPrice(price)}</strong>
      {originalPrice !== undefined && originalPrice > price && (
        <del className="price-display-original">{formatPrice(originalPrice)}</del>
      )}
    </p>
  );
}

